const results = [];

for (const item of $input.all()) {
  let raw = item.json.text;

  if (typeof raw !== 'string') {
    throw new Error(
      `Expected text from AI Search Planner. Available fields: ${Object.keys(item.json).join(', ')}`
    );
  }

  raw = raw.trim()
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/, '');

  let plan;

  try {
    plan = JSON.parse(raw);
  } catch {
    throw new Error(
      `AI Search Planner returned invalid JSON: ${raw.slice(0, 300)}`
    );
  }

  const missing = [];

  if (!plan.request_id) missing.push('request_id');
  if (!plan.business_type) missing.push('business_type');
  if (!plan.location) missing.push('location');

  if (
    !Array.isArray(plan.search_queries) ||
    plan.search_queries.length === 0
  ) {
    missing.push('search_queries');
  }

  if (missing.length) {
    throw new Error(
      `AI search plan is missing: ${missing.join(', ')}. ` +
      `Returned fields: ${Object.keys(plan).join(', ')}`
    );
  }

  results.push({ json: plan });
}

return results;

const items = $input.all();
let pagination = {};

try {
  pagination = $('Goto Serp API').first().json;
} catch (error) {
  pagination = {};
}



// Get current request metadata
const request = $('Generate Search Pages').first().json;

const turn = Number(pagination.start ?? request.start ?? 0);
const pageNumber = Number(
  pagination.page_number ?? request.page_number ?? 1
);

console.log("Page Number " + pageNumber.toString())
console.log("Start " + turn.toString())

const clean = value => String(value ?? '').trim();

const normalizeDomain = value => {
  if (!value) return '';

  return clean(value)
    .replace(/^https?:\/\//i, '')
    .replace(/^www\./i, '')
    .split(/[/?#]/)[0]
    .split(':')[0]
    .toLowerCase();
};

const output = [];

for (const item of items) {
  const response = item.json ?? {};

  const results = Array.isArray(response.local_results)
    ? response.local_results
    : [];

  for (const result of results) {
    const name = clean(result.title || result.name);

    if (!name) continue;

    const website = clean(result.website);

    output.push({
      json: {
        request_id: request.request_id ?? '',
        company_name: name,
        place_id: clean(result.place_id || result.data_id),
        website,
        company_domain: normalizeDomain(website),
        business_phone: clean(result.phone),
        address: clean(result.address),

        country: request.country ?? 'United States',
        state: request.state ?? '',
        city: request.city ?? '',

        latitude: result.gps_coordinates?.latitude ?? null,
        longitude: result.gps_coordinates?.longitude ?? null,

        business_type: request.business_type ?? '',
        source: 'serpapi_google_maps',
        source_url: website || clean(result.link),

        public_business_emails: [],
        contact_status: 'needs_verification',

        rating: result.rating ?? null,
        reviews: result.reviews ?? null,
        categories: result.type ? [result.type] : [],

        search_query: request.search_queries ?? '',

        // Pagination from Generate Search Pages
        start: turn,
        page_number: pageNumber,
        page_limit: Number(request.page_limit ?? 20),
        max_pages: Number(request.max_pages ?? 2)
      }
    });
  }
}

return output;

const items = $input.all();

const seen = new Set();
const cleaned = [];

const MAX_LEADS = 100;

const clean = value => String(value ?? '').trim();

const normalizeDomain = value => {
  return clean(value)
    .replace(/^https?:\/\//i, '')
    .replace(/^www\./i, '')
    .split(/[/?#]/)[0]
    .split(':')[0]
    .toLowerCase();
};

// Get pagination from current input first.
let pagination = items.find(item =>
  item.json?.page_number !== undefined
)?.json;

// If no input record, get pagination from Deduplicate Businesses.
if (!pagination) {
  pagination = $('Deduplicate Businesses').first().json ?? {};
}

const start = Number(pagination.start ?? 0);
const pageNumber = Number(pagination.page_number ?? 1);
const pageLimit = Number(pagination.page_limit ?? 20);
const maxPages = Number(pagination.max_pages ?? 10);
const requestId = pagination.request_id ?? '';


for (const item of items) {
  const lead = item.json ?? {};

  const name = clean(lead.company_name);

  if (!name) continue;

  const website = clean(lead.website);
  const domain = normalizeDomain(
    lead.company_domain || website
  );

  const placeId = clean(lead.place_id).toLowerCase();
  const address = clean(lead.address);

  const key = placeId
    ? `place:${placeId}`
    : domain
      ? `domain:${domain}`
      : `name:${name.toLowerCase()}|${address.toLowerCase()}`;

  if (seen.has(key)) continue;

  const emails = [
    ...(Array.isArray(lead.public_business_emails)
      ? lead.public_business_emails
      : []),
    lead.business_email,
    lead.email
  ]
    .map(clean)
    .filter(Boolean);

  const phones = [
    lead.business_phone,
    lead.phone,
    lead.mobile_phone,
    ...(Array.isArray(lead.candidate_business_phones)
      ? lead.candidate_business_phones
      : [])
  ]
    .map(clean)
    .filter(Boolean);

  // Require at least one contact method.
  if (emails.length === 0 && phones.length === 0) continue;

  seen.add(key);

  cleaned.push({
    json: {
      ...lead,
      company_name: name,
      website,
      company_domain: domain,
      address,
      business_phone: phones[0] ?? '',
      public_business_emails: [...new Set(emails)],
      candidate_business_phones: [...new Set(phones)],
      lead_status: 'discovered',

      // Pagination metadata
      start,
      page_number: pageNumber,
      page_limit: pageLimit,
      max_pages: maxPages,
      has_leads: true
    }
  });

  if (cleaned.length >= MAX_LEADS) break;
}

// No valid leads: return pagination control item.
if (cleaned.length === 0) {
  return [{
    json: {
      request_id: requestId,
      start,
      page_number: pageNumber,
      page_limit: pageLimit,
      max_pages: maxPages,
      has_leads: false,
      total_cleaned: 0
    }
  }];
}

return cleaned;

const items = $input.all();
const output = [];

const MAX_HTML = 300000;
const MAX_TEXT = 100000;
const MAX_EMAILS = 20;
const MAX_PHONES = 20;

const EMAIL_REGEX =
  /[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}/gi;

const TEL_REGEX =
  /href\s*=\s*["']\s*tel:([^"']+)["']/gi;

const PHONE_REGEX =
  /\+?\d[\d\s().-]{6,20}\d/g;

const CONTACT_LINK_REGEX =
  /<a\b[^>]*href\s*=\s*["']([^"']+)["'][^>]*>/gi;

function decodeHtml(value) {
  return String(value ?? '')
    .replace(/&commat;/gi, '@')
    .replace(/&period;/gi, '.')
    .replace(/&plus;/gi, '+')
    .replace(/&colon;/gi, ':')
    .replace(/&amp;/gi, '&')
    .replace(/&#64;|&#x40;/gi, '@')
    .replace(/&#46;|&#x2e;/gi, '.')
    .replace(/&#43;|&#x2b;/gi, '+')
    .replace(/&#(\d+);/g, (_, n) =>
      String.fromCharCode(Number(n))
    )
    .replace(/&#x([a-f0-9]+);/gi, (_, n) =>
      String.fromCharCode(parseInt(n, 16))
    );
}

function normalizeEmail(value) {
  const email = decodeHtml(value)
    .trim()
    .toLowerCase()
    .replace(/^mailto:/i, '')
    .split('?')[0];

  if (!email || email.length > 254) return null;

  if (!/^[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}$/i.test(email)) {
    return null;
  }

  if (
    /\.(png|jpg|jpeg|gif|svg|webp|css|js|woff2?)$/i.test(email)
  ) {
    return null;
  }

  if (
    /@(example\.com|test\.com|localhost)$/i.test(email)
  ) {
    return null;
  }

  return email;
}

function normalizePhone(value) {
  const phone = decodeHtml(value)
    .replace(/^tel:/i, '')
    .split(/[;,?]/)[0]
    .trim();

  if (!/^\+?[\d\s().-]+$/.test(phone)) return null;

  const digits = phone.replace(/\D/g, '');

  if (digits.length < 7 || digits.length > 15) return null;
  if (/^(\d)\1+$/.test(digits)) return null;

  return phone;
}

function getHtml(lead) {
  const candidates = [
    lead.website_fetch,
    lead.body,
    lead.data,
    lead.markdown,
    lead.data?.markdown
  ];

  for (const value of candidates) {
    if (typeof value === 'string' && value.length) {
      return value;
    }
  }

  return '';
}

function resolveContactLink(href, website) {
  const decoded = decodeHtml(href).trim();

  if (
    !decoded ||
    /^(mailto:|tel:|javascript:|#)/i.test(decoded)
  ) {
    return '';
  }

  try {
    return new URL(decoded, website || undefined).href;
  } catch {
    return decoded;
  }
}

for (const item of items) {
  const lead = item.json || {};

  try {
    const html = getHtml(lead);
    const limitedHtml = html.slice(0, MAX_HTML);

    const errorMessage =
      typeof lead.error === 'string'
        ? lead.error
        : lead.error?.message ?? '';

    const blocked =
      Boolean(lead.error) ||
      /cloudflare|cf-challenge|challenge-platform|just a moment|checking your browser|access denied|captcha|robot check/i.test(
        limitedHtml.slice(0, 5000)
      );

    const emails = new Set(
      (Array.isArray(lead.public_business_emails)
        ? lead.public_business_emails
        : []
      )
        .map(normalizeEmail)
        .filter(Boolean)
    );

    const phones = new Map();

    const existingPhones = Array.isArray(
      lead.candidate_business_phones
    )
      ? lead.candidate_business_phones
      : [];

    for (const value of existingPhones) {
      const phone = normalizePhone(value);

      if (phone) {
        phones.set(phone.replace(/\D/g, ''), phone);
      }
    }

    let contactPageLink = lead.contact_page_link ?? '';

    if (!blocked && limitedHtml) {
      // Extract emails from HTML
      let match;
      EMAIL_REGEX.lastIndex = 0;

      while (
        (match = EMAIL_REGEX.exec(limitedHtml)) !== null &&
        emails.size < MAX_EMAILS
      ) {
        const email = normalizeEmail(match[0]);

        if (email) emails.add(email);
      }

      // Extract telephone links
      TEL_REGEX.lastIndex = 0;

      while (
        (match = TEL_REGEX.exec(limitedHtml)) !== null &&
        phones.size < MAX_PHONES
      ) {
        const phone = normalizePhone(match[1]);

        if (phone) {
          phones.set(phone.replace(/\D/g, ''), phone);
        }
      }

      // Extract phone candidates from visible text
      const text = limitedHtml
        .replace(/<!--[\s\S]*?-->/g, ' ')
        .replace(/<(script|style|noscript|svg|head)\b[^>]*>[\s\S]*?<\/\1>/gi, ' ')
        .replace(/<[^>]*>/g, ' ')
        .slice(0, MAX_TEXT);

      PHONE_REGEX.lastIndex = 0;

      while (
        (match = PHONE_REGEX.exec(text)) !== null &&
        phones.size < MAX_PHONES
      ) {
        const phone = normalizePhone(match[0]);

        if (phone) {
          phones.set(phone.replace(/\D/g, ''), phone);
        }
      }

      // Find a contact/about page link if not already available
      if (!contactPageLink) {
        CONTACT_LINK_REGEX.lastIndex = 0;

        while (
          (match = CONTACT_LINK_REGEX.exec(limitedHtml)) !== null
        ) {
          const href = match[1];

          if (
            /contact|about-us|about|contact-us/i.test(href)
          ) {
            contactPageLink = resolveContactLink(
              href,
              lead.website
            );

            if (contactPageLink) break;
          }
        }
      }
    }

    const finalEmails = [...emails].slice(0, MAX_EMAILS);
    const finalPhones = [...phones.values()].slice(0, MAX_PHONES);

    const hasContacts = finalEmails.length > 0 ||
      finalPhones.length > 0 ||
      Boolean(lead.business_phone);

    output.push({
      json: {
        ...lead,

        public_business_emails: finalEmails,
        candidate_business_phones: finalPhones,

        contact_page_link: contactPageLink,
        contact_source_url:
          lead.contact_source_url || lead.website || '',

        website_fetch_status: blocked
          ? 'blocked_or_failed'
          : html
            ? 'fetched'
            : 'no_html',

        contact_extraction_status: blocked
          ? 'website_unavailable'
          : hasContacts
            ? 'contacts_found'
            : 'no_contacts_found',

        extraction_truncated: html.length > MAX_HTML,

        extraction_error: blocked
          ? errorMessage || 'Website blocked or unavailable'
          : ''
      }
    });

  } catch (error) {
    output.push({
      json: {
        ...lead,

        public_business_emails:
          lead.public_business_emails ?? [],

        candidate_business_phones:
          lead.candidate_business_phones ?? [],

        contact_page_link:
          lead.contact_page_link ?? '',

        contact_source_url:
          lead.contact_source_url || lead.website || '',

        website_fetch_status: 'extraction_error',
        contact_extraction_status: 'failed',
        extraction_error: String(error)
      }
    });
  }
}

return output;

const items = $input.all();

return items.map(item => {
  const lead = item.json;

  const emails = [
    ...new Set(
      (lead.public_business_emails ?? [])
        .map(v => String(v).trim().toLowerCase())
        .filter(email =>
          /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) &&
          !/^(you|your|name|email|test)@/i.test(email) &&
          !/@(sentry\.io|sentry\.wixpress\.com|sentry-next\.wixpress\.com)$/i.test(email)
        )
    )
  ];

  const phoneMap = new Map();

  for (const value of lead.candidate_business_phones ?? []) {
    const phone = String(value).trim();
    const digits = phone.replace(/\D/g, '');

    if (digits.length < 10 || digits.length > 15) continue;

    if (!phoneMap.has(digits)) {
      phoneMap.set(digits, phone);
    }
  }

  const website = String(lead.website ?? '').trim();
  const companyDomain = website
    .replace(/^https?:\/\//i, '')
    .replace(/^www\./i, '')
    .split(/[/?#]/)[0]
    .split(':')[0]
    .toLowerCase();

  return {
    json: {
      request_id: lead.request_id ?? '',
      business_type: lead.business_type ?? '',
      location: lead.location ?? '',
      company_name: lead.company_name ?? '',
      place_id: lead.place_id ?? '',
      address: lead.address ?? '',
      country: lead.country ?? '',
      website,
      company_domain: companyDomain,
      start: lead.start ?? 0,
      page_number: lead.page_number ?? 1,
      max_pages: lead.max_pages ?? 3,

      business_phone: String(lead.business_phone ?? '').trim(),
      public_business_emails: emails,
      candidate_business_phones: [...phoneMap.values()],
      description: lead.description ?? '',
      rating: lead.rating ?? null,
      reviews: lead.reviews ?? null,
      latitude: lead.latitude ?? null,
      longitude: lead.longitude ?? null,
      contact_source_url: lead.contact_source_url || website,
      website_fetch_status: lead.website_fetch_status ??
      (website ? 'not_attempted' : 'no_website'),
      contact_review_status: 'needs_verification',
      lead_status: lead.lead_status || 'discovered'
    }
  };
});

const items = $input.all();

const leadsMap = new Map();

const clean = value => String(value ?? '').trim();

const normalizeText = value =>
  clean(value)
    .toLowerCase()
    .replace(/[^\p{L}\p{N}]/gu, '');

const normalizeDomain = value =>
  clean(value)
    .toLowerCase()
    .replace(/^https?:\/\//i, '')
    .replace(/^www\./i, '')
    .split(/[/?#]/)[0]
    .split(':')[0];

const getEmails = lead => [
  ...(Array.isArray(lead.public_business_emails)
    ? lead.public_business_emails
    : []),
  lead.business_email,
  lead.email
].map(clean).filter(Boolean);

const getPhones = lead => [
  lead.business_phone,
  lead.phone,
  lead.mobile_phone,
  ...(Array.isArray(lead.candidate_business_phones)
    ? lead.candidate_business_phones
    : [])
].map(clean).filter(Boolean);

for (const item of items) {
  const lead = item.json ?? {};

  const name = normalizeText(lead.company_name || lead.name);
  const address = normalizeText(lead.address);
  const domain = normalizeDomain(
    lead.company_domain || lead.website
  );
  const placeId = clean(lead.place_id).toLowerCase();

  if (!name && !placeId && !domain) continue;

  const key = placeId
    ? `place:${placeId}`
    : domain
      ? `domain:${domain}`
      : address
        ? `name-address:${name}|${address}`
        : `name:${name}`;

  const existing = leadsMap.get(key);

  if (!existing) {
    leadsMap.set(key, {
      ...lead,
      public_business_emails: [...new Set(getEmails(lead))],
      candidate_business_phones: [...new Set(getPhones(lead))]
    });

    continue;
  }

  // Preserve existing values and fill missing fields.
  for (const [field, value] of Object.entries(lead)) {
    if (
      (existing[field] === null ||
       existing[field] === undefined ||
       existing[field] === '') &&
      value !== null &&
      value !== undefined &&
      value !== ''
    ) {
      existing[field] = value;
    }
  }

  // Merge emails and phone numbers.
  existing.public_business_emails = [
    ...new Set([
      ...existing.public_business_emails,
      ...getEmails(lead)
    ])
  ];

  existing.candidate_business_phones = [
    ...new Set([
      ...existing.candidate_business_phones,
      ...getPhones(lead)
    ])
  ];

  existing.has_contact =
    existing.public_business_emails.length > 0 ||
    existing.candidate_business_phones.length > 0;
}

return [...leadsMap.values()].map(lead => ({
  json: lead
}));

const queries = $input.all();

return queries.map(item => {
  const data = item.json ?? {};

  const start = Number(data.start ?? 0);
  const pageNumber = Number(data.page_number ?? 1);
  const pageLimit = Number(data.page_limit ?? 20);
  const maxPages = Number(data.max_pages ?? 5);

  return {
    json: {
      ...data,

      // SerpApi pagination
      start,
      page_limit: pageLimit,
      page_number: pageNumber,
      max_pages: maxPages,
      has_more_pages: pageNumber <= maxPages,

      // TomTom pagination
      tomtom_offset: Number(data.tomtom_offset ?? 0),
      tomtom_page_number: Number(data.tomtom_page_number ?? 1),
      tomtom_page_limit: Number(data.tomtom_page_limit ?? 20),
      tomtom_max_pages: Number(data.tomtom_max_pages ?? 3)
    }
  };
});

const incoming = $('Normalize Business Results').all()
  .map(item => item.json);

const existingRows = $input.all()
  .map(item => item.json);

const normalize = value =>
  String(value ?? '').trim().toLowerCase();

const cleanDomain = value =>
  normalize(value)
    .replace(/^https?:\/\//i, '')
    .replace(/^www\./i, '')
    .split(/[/?#]/)[0]
    .replace(/\/+$/, '');

const existingDomains = new Set();
const existingPlaceIds = new Set();
const existingNamesAndAddresses = new Set();

for (const row of existingRows) {
  const domain = cleanDomain(row.company_domain);
  if (domain) existingDomains.add(domain);

  const placeId = normalize(row.place_id);
  if (placeId) existingPlaceIds.add(placeId);

  const name = normalize(row.company_name);
  const address = normalize(row.address);

  if (name && address) {
    existingNamesAndAddresses.add(`${name}|${address}`);
  }
}

const seenIncomingDomains = new Set();
const seenIncomingPlaceIds = new Set();
const seenIncomingNamesAndAddresses = new Set();

const newLeads = [];

for (const lead of incoming) {
  const domain = cleanDomain(lead.company_domain);
  const placeId = normalize(lead.place_id);
  const name = normalize(lead.company_name);
  const address = normalize(lead.address);
  const nameAddress = name && address ? `${name}|${address}` : '';

  if (domain && existingDomains.has(domain)) continue;
  if (placeId && existingPlaceIds.has(placeId)) continue;

  if (nameAddress && existingNamesAndAddresses.has(nameAddress)) continue;

  if (domain && seenIncomingDomains.has(domain)) continue;
  if (placeId && seenIncomingPlaceIds.has(placeId)) continue;

  if (nameAddress && seenIncomingNamesAndAddresses.has(nameAddress)) continue;

  if (domain) seenIncomingDomains.add(domain);
  if (placeId) seenIncomingPlaceIds.add(placeId);
  if (nameAddress) seenIncomingNamesAndAddresses.add(nameAddress);

  newLeads.push({ json: lead });
}

return newLeads;

const page = $input.first().json;

const currentStart = Number(page.start ?? 0);
const currentPage = Number(page.page_number ?? 1);
const pageLimit = Number(page.page_limit ?? 20);
const maxPages = Number(page.max_pages ?? 10);

console.log('========== UPDATE OFFSET ==========');
console.log('Current Start:', currentStart);
console.log('Current Page:', currentPage);
console.log('Page Limit:', pageLimit);
console.log('Max Pages:', maxPages);

// Validate pagination values
if (
  !Number.isInteger(currentStart) ||
  !Number.isInteger(currentPage) ||
  !Number.isInteger(pageLimit) ||
  !Number.isInteger(maxPages) ||
  currentStart < 0 ||
  currentPage < 1 ||
  pageLimit <= 0 ||
  maxPages < 1
) {
  throw new Error('Invalid pagination state');
}

// Calculate next page
const nextPage = currentPage + 1;
const nextStart = currentStart + pageLimit;

const hasMorePages = nextPage <= maxPages;

console.log('Next Start:', nextStart);
console.log('Next Page:', nextPage);
console.log('Has More Pages:', hasMorePages);
console.log('===================================');

return [{
  json: {
    ...page,
    start: nextStart,
    page_number: nextPage,
    page_limit: pageLimit,
    max_pages: maxPages,
    has_more_pages: hasMorePages,
    pagination_status: hasMorePages ? 'continue' : 'completed'
  }
}];

const items = $input.all();
const output = [];

const requestId =
  $('Generate Search Pages').first().json.request_id ?? null;

const clean = value => String(value ?? '').trim();

const normalizeDomain = value => {
  if (!value) return null;

  return String(value)
    .trim()
    .replace(/^https?:\/\//i, '')
    .replace(/^www\./i, '')
    .split(/[/?#]/)[0]
    .toLowerCase() || null;
};

for (const item of items) {
  const response = item.json;

  // TomTom Search API commonly returns results in "results".
  // Also support a direct POI object or an array input.
  const results = Array.isArray(response.results)
    ? response.results
    : Array.isArray(response)
      ? response
      : response.poi || response.position
        ? [response]
        : [];

  for (const result of results) {
    const poi = result.poi ?? result;
    const addressData = result.address ?? {};
    const position = result.position ?? {};

    const companyName = clean(
      poi.name ?? result.name ?? result.title
    );

    if (!companyName) continue;

    const website =
      poi.url ??
      result.url ??
      result.website ??
