const items = $input.all();

const output = [];
const seen = new Map();

// --------------------------------------------------
// 1. BASIC HELPERS
// --------------------------------------------------

const clean = value =>
  value == null ? '' : String(value).trim();

const normalizeText = value =>
  clean(value)
    .toLowerCase()
    .replace(/[^\p{L}\p{N}]/gu, '');

const normalizeDomain = value => {
  let domain = clean(value).toLowerCase();

  if (!domain) return '';

  return domain
    .replace(/^https?:\/\//i, '')
    .replace(/^www\./i, '')
    .split(/[/?#]/)[0]
    .split(':')[0];
};

const isEmpty = value =>
  value == null ||
  (typeof value === 'string' && value.trim() === '') ||
  (Array.isArray(value) && value.length === 0);

const splitValues = value => {
  if (Array.isArray(value)) return value;
  if (value == null || value === '') return [];
  return String(value).split(',');
};

const mergeArray = (a, b, normalize = normalizeText) => {
  const values = [...splitValues(a), ...splitValues(b)]
    .map(clean)
    .filter(Boolean);

  const unique = new Map();

  for (const value of values) {
    const key = normalize(value);

    if (key && !unique.has(key)) {
      unique.set(key, value);
    }
  }

  return [...unique.values()];
};

const mergeStringList = (a, b, normalize) =>
  mergeArray(a, b, normalize).join(', ');

// --------------------------------------------------
// 2. PARSE REDIS RECORDS
// --------------------------------------------------

const parseLead = value => {
  if (typeof value === 'string') {
    try {
      return JSON.parse(value);
    } catch {
      return null;
    }
  }

  return value && typeof value === 'object'
    ? value
    : null;
};

const collectLeads = (value, depth = 0) => {
  if (depth > 10 || value == null) return [];

  const parsed = parseLead(value);

  if (!parsed) return [];

  if (Array.isArray(parsed)) {
    return parsed.flatMap(record =>
      collectLeads(record, depth + 1)
    );
  }

  // Actual lead record.
  if (
    parsed.place_id ||
    parsed.company_name ||
    parsed.business_name
  ) {
    return [parsed];
  }

  // Redis wrappers.
  for (const key of ['result', 'leads', 'data', 'value']) {
    if (parsed[key] != null) {
      return collectLeads(parsed[key], depth + 1);
    }
  }

  return [];
};

// --------------------------------------------------
// 3. DEDUPLICATION KEY
// --------------------------------------------------

const getLeadKey = lead => {
  const placeId = clean(lead.place_id).toLowerCase();

  const domain = normalizeDomain(
    lead.company_domain || lead.website
  );

  const name = normalizeText(
    lead.company_name ||
    lead.name ||
    lead.business_name
  );

  const address = normalizeText(lead.address);

  if (placeId) return `place:${placeId}`;

  if (domain) return `domain:${domain}`;

  if (name && address)
    return `name-address:${name}|${address}`;

  if (name) return `name:${name}`;

  return '';
};

// --------------------------------------------------
// 4. MERGE DUPLICATE LEADS
// --------------------------------------------------

const mergeLeads = (existing, incoming) => {
  const merged = { ...existing };

  // Preserve missing fields.
  for (const [key, value] of Object.entries(incoming)) {
    if (isEmpty(merged[key]) && !isEmpty(value)) {
      merged[key] = value;
    }
  }

  // Merge public emails.
  merged.public_business_emails = mergeArray(
    existing.public_business_emails,
    incoming.public_business_emails,
    value => clean(value).toLowerCase()
  );

  // Merge candidate phones.
  merged.candidate_business_phones = mergeArray(
    existing.candidate_business_phones,
    incoming.candidate_business_phones,
    value => clean(value).replace(/\D/g, '')
  );

  // Merge extracted emails.
  merged.business_emails = mergeStringList(
    existing.business_emails,
    [
      incoming.business_emails,
      ...merged.public_business_emails,
      incoming.business_email,
      incoming.email
    ],
    value => clean(value).toLowerCase()
  );

  // Merge extracted phones.
  merged.business_phones = mergeStringList(
    existing.business_phones,
    [
      incoming.business_phones,
      existing.business_phone,
      incoming.business_phone,
      ...merged.candidate_business_phones,
      incoming.phone,
      incoming.mobile_phone
    ],
    value => clean(value).replace(/\D/g, '')
  );

  return merged;
};

// --------------------------------------------------
// 5. READ AND DEDUPLICATE ALL REDIS RECORDS
// --------------------------------------------------

for (const item of items) {
  const records = collectLeads(item.json ?? {});

  for (const lead of records) {
    const key = getLeadKey(lead);

    if (!key) continue;

    if (seen.has(key)) {
      const index = seen.get(key);

      output[index].json = mergeLeads(
        output[index].json,
        lead
      );

    } else {
      seen.set(key, output.length);

      output.push({
        json: { ...lead }
      });
    }
  }
}

// --------------------------------------------------
// 6. FINAL CONTACT CONSOLIDATION
// --------------------------------------------------

for (const item of output) {
  const lead = item.json;

  lead.business_emails = mergeStringList(
    lead.business_emails,
    [
      lead.public_business_emails,
      lead.business_email,
      lead.email
    ],
    value => clean(value).toLowerCase()
  );

  lead.business_phones = mergeStringList(
    lead.business_phones,
    [
      lead.business_phone,
      lead.candidate_business_phones,
      lead.phone,
      lead.mobile_phone
    ],
    value => clean(value).replace(/\D/g, '')
  );
}

// --------------------------------------------------
// 7. RETURN ONE N8N ITEM WITH ALL UNIQUE LEADS
// --------------------------------------------------


// --------------------------------------------------
// 7. RETURN INDIVIDUAL LEADS WITH has_leads INTACT
// --------------------------------------------------

if (output.length === 0) {
  return [{
    json: {
      has_leads: false,
      total_leads: 0,
      result: [],
      message: 'No eligible leads found after parsing and deduplication.'
    }
  }];
}

// Return one n8n item per unique lead.
return output.map(item => ({
  json: {
    ...item.json,
    has_leads: true,
    total_leads: output.length
  }
}));

const page = $input.first().json;


const currentStart = Number(page.start ?? 0);
const currentPage = Number(page.page_number ?? 1);
const pageLimit = Number(page.page_limit ?? 20);
const maxPages = Number(page.max_pages ?? 5);

console.log('========== UPDATE OFFSET ==========');
console.log('Current Start:', currentStart);
console.log('Current Page:', currentPage);

console.log('===================================');


// Validate pagination values
if (
  !Number.isFinite(currentStart) ||
  !Number.isFinite(currentPage) ||
  !Number.isFinite(pageLimit) ||
  !Number.isFinite(maxPages) ||
  pageLimit <= 0
) {
  throw new Error('Invalid pagination state');
}

// Calculate next page
const nextPage = currentPage ;
const nextStart = currentStart ;


return [{
  json: {
    ...page,
    start: nextStart,
    page_number: nextPage,
    page_limit: pageLimit,
    max_pages: maxPages,
    has_more_pages: nextPage <= maxPages,
    debug: {
      node: "Update Offset",
      current_start: currentStart,
      current_page: currentPage,
      next_start: nextStart,
      next_page: nextPage
    }
  }
}];

const items = $input.all();

const leads = items
  .map(item => item.json)
  .filter(lead =>
    lead &&
    typeof lead === 'object' &&
    (lead.place_id || lead.company_name || lead.name)
  )
  .map(lead => {
    const emails = [
      ...(Array.isArray(lead.public_business_emails)
        ? lead.public_business_emails
        : []),
      lead.business_email,
      lead.email
    ]
      .filter(Boolean)
      .map(value => String(value).trim())
      .filter(Boolean);

    const phones = [
      lead.business_phone,
      ...(Array.isArray(lead.candidate_business_phones)
        ? lead.candidate_business_phones
        : []),
      lead.phone,
      lead.mobile_phone
    ]
      .filter(Boolean)
      .map(value => String(value).trim())
      .filter(Boolean);

    return {
      ...lead,
      company_name: lead.company_name ?? lead.name ?? '',
      public_business_emails: [...new Set(emails)],
      candidate_business_phones: [...new Set(phones)],
      has_contact: emails.length > 0 || phones.length > 0
    };
  });

// Keep only leads with a phone number or email.
const eligibleLeads = leads.filter(lead => lead.has_contact);

// Validate pagination consistency.
const getSingleValue = (field, fallback) => {
  const values = [
    ...new Set(
      leads
        .map(lead => lead[field])
        .filter(value => value !== undefined && value !== null && value !== '')
        .map(Number)
    )
  ];

  if (values.length > 1) {
    throw new Error(`Multiple ${field} values found in this batch.`);
  }

  return values.length ? values[0] : fallback;
};

const start = getSingleValue('start', 0);
const page_number = getSingleValue('page_number', 1);
const max_pages = getSingleValue('max_pages', 1);

// Validate request ID.
const requestIds = [
  ...new Set(
    leads.map(lead => lead.request_id).filter(Boolean)
  )
];

if (requestIds.length > 1) {
  throw new Error('Multiple request_id values found.');
}

const requestId = requestIds[0] ?? null;

if (eligibleLeads.length > 0 && !requestId) {
  throw new Error('request_id is missing from eligible leads.');
}

const redisKey = requestId
  ? `leads:${requestId}`
  : null;

return [{
  json: {
    request_id: requestId,
    start,
    page_number,
    max_pages,

    total_received: leads.length,
    eligible_count: eligibleLeads.length,
    rejected_count: leads.length - eligibleLeads.length,

    lead_count: eligibleLeads.length,
    redis_key: redisKey,
    skip_redis: eligibleLeads.length === 0,

    redis_command: eligibleLeads.length > 0
      ? [
          'RPUSH',
          redisKey,
          ...eligibleLeads.map(lead => JSON.stringify(lead))
        ]
      : null
  }
}];

const data = $input.first().json;

return [{
  json: {
    ...data,

    redis_save_status: 'failed',

    failed_prefix: data.failed_prefix ?? null,
    failed_request_id: data.request_id,
    failed_start: data.start,
    failed_page_number: data.page_number,
    failed_max_pages: data.max_pages,
    failed_lead_count: data.lead_count,

    error_message:
      data.error?.message ??
      data.message ??
      data.failed_prefix ??
      'Redis save failed'
  }
}];

const items = $input.all();

return items.map(item => {
  const data = item.json ?? {};

  return {
