        data.message ??
        'SerpApi request failed',

      error_status:
        data.error?.httpCode ??
        data.statusCode ??
        null,

      error_time: new Date().toISOString(),
      error_status_type: 'failed'
    }
  };
});

const items = $input.all();
const data = items[0]?.json ?? {};

const httpStatus = Number(data.http_status ?? 200);
const executionSource =
  $('Validate Search Request').first().json.execution_source;

const allowedStatuses = [
  200, 201, 202, 400, 401, 403,
